# Router Context
## Using the Router Context [#](https://tanstack.com/router/v1/docs/guide/router-context#using-the-router-context)
### How about an external data fetching library? [#](https://tanstack.com/router/v1/docs/guide/router-context#how-about-an-external-data-fetching-library)
```
import {
  createRootRouteWithContext,
  createRouter,
} from '@tanstack/react-router'

interface MyRouterContext {
  queryClient: QueryClient
}

const rootRoute = createRootRouteWithContext<MyRouterContext>()({
  component: App,
})

const queryClient = new QueryClient()

const router = createRouter({
  routeTree: rootRoute,
  context: {
    queryClient,
  },
})
```

## How about using React Context/Hooks? [#](https://tanstack.com/router/v1/docs/guide/router-context#how-about-using-react-context-hooks)
```
// First, make sure the context for the root route is typed
import { createRootRouteWithContext } from '@tanstack/react-router'
import { useNetworkStrength } from '@/hooks/useNetworkStrength'

interface MyRouterContext {
  networkStrength: ReturnType<typeof useNetworkStrength>
}

export const Route = createRootRouteWithContext<MyRouterContext>()({
  component: App,
})
```

## Modifying the Router Context [#](https://tanstack.com/router/v1/docs/guide/router-context#modifying-the-router-context)
