## Processing Accumulated Route Context [#](https://tanstack.com/router/v1/docs/guide/router-context#processing-accumulated-route-context)
```
export const Route = createRootRoute({
  component: () => {
    const matches = useRouterState({ select: (s) => s.matches })

    const matchWithTitle = [...matches]
      .reverse()
      .find((d) => d.context.getTitle)

    const title = matchWithTitle?.context.getTitle() || 'My App'

    return (
      <html>
        <head>
          <title>{title}</title>
        </head>
        <body>{/* ... */}</body>
      </html>
    )
  },
})
```

# [React Tanstack Start/Router: Where do I put providers?](https://stackoverflow.com/questions/79635745/react-tanstack-start-router-where-do-i-put-providers)
So far I have about 3 that I need for my app between context, libraries, and authentication.

## 1 Answer 1
```javascript
Copy
// app/routes/__root.tsx
import {
  Outlet,
  createRootRoute,
  HeadContent,
  Scripts,
} from '@tanstack/react-router'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { AuthProvider } from '~/lib/auth'
import { ThemeProvider } from '~/lib/theme'

const queryClient = new QueryClient()

export const Route = createRootRoute({
  component: RootComponent,
})

function RootComponent() {
  return (
    <RootDocument>
      {/* providers go here */}
      <QueryClientProvider client={queryClient}>
        <AuthProvider>
          <ThemeProvider>
            {/* all your route components render inside <Outlet /> */}
            <Outlet />
          </ThemeProvider>
        </AuthProvider>
      </QueryClientProvider>
    </RootDocument>
  )
}

function RootDocument({ children }: { children: React.ReactNode }) {
  return (
    <html>
      <head>
        <HeadContent />
      </head>
      <body>
        {children}
        <Scripts />
      </body>
    </html>
  )
}
```

```javascript
Copy
import { hydrateRoot } from 'react-dom/client'
import { StartClient } from '@tanstack/react-start'
import { createRouter } from './router'

hydrateRoot(document, <StartClient router={createRouter()} />)
```

`<StartClient />` must be the root element that hydrates the markup sent by the server.

# Selective Server-Side Rendering (SSR)
## How to disable SSR of the root route? [#](https://tanstack.com/start/v0/docs/framework/react/guide/selective-ssr#how-to-disable-ssr-of-the-root-route)
```
import * as React from 'react'

import {
  HeadContent,
  Outlet,
  Scripts,
  createRootRoute,
} from '@tanstack/react-router'

export const Route = createRootRoute({
  shellComponent: RootShell,
  component: RootComponent,
  errorComponent: () => <div>Error</div>,
  notFoundComponent: () => <div>Not found</div>,
  ssr: false, // or `defaultSsr: false` on the router
})

function RootShell({ children }: { children: React.ReactNode }) {
  return (
    <html>
      <head>
        <HeadContent />
      </head>
      <body>
        {children}
        <Scripts />
      </body>
    </html>
  )
}

function RootComponent() {
  return (
    <div>
      <h1>This component will be rendered on the client</h1>
      <Outlet />
    </div>
  )
}
```

# Type Safety
## Fixing the Component Context Problem [#](https://tanstack.com/router/v1/docs/guide/type-safety#fixing-the-component-context-problem)
```
export const Route = createFileRoute('/posts')({
  component: PostsComponent,
})

function PostsComponent() {
  // Each route has type-safe versions of most of the built-in hooks from TanStack Router
  const params = Route.useParams()
  const search = Route.useSearch()

  // Some hooks require context from the *entire* router, not just the current route. To achieve type-safety here,
  // we must pass the `from` param to tell the hook our relative position in the route hierarchy.
  const navigate = useNavigate({ from: Route.fullPath })
  // ... etc
}
```

Every hook and component that requires a context hint will have a from param where you can pass the ID or path of the route you are rendering within.

## Router Context [#](https://tanstack.com/router/v1/docs/guide/type-safety#router-context)
```
const rootRoute = createRootRouteWithContext<{ whateverYouWant: true }>()({
  component: App,
})

const routeTree = rootRoute.addChildren([\
  // ... all child routes will have access to `whateverYouWant` in their context\
])

const router = createRouter({
  routeTree,
  context: {
    // This will be required to be passed now
    whateverYouWant: true,
  },
})
```

